args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?spouse ?spouseLabel ?deathPlace ?deathPlaceLabel WHERE {
  {
    dbr:Paulding_Farnham dbo:spouse ?spouse .
  }
  UNION
  {
    dbr:Paulding_Farnham dbp:spouse ?spouse .
    FILTER(isIRI(?spouse))
  }
  OPTIONAL { ?spouse dbo:deathPlace ?deathPlace . }
  OPTIONAL { ?spouse dbp:deathPlace ?deathPlace . FILTER(isIRI(?deathPlace)) }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel FILTER(lang(?spouseLabel) = "en") }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel FILTER(lang(?deathPlaceLabel) = "en") }
}

